'use strict';
// WP09 R3 / R11 / R12(f): the precache list (sw-precache.js, generated by scripts/gen-precache.mjs) against the filesystem
// and against every asset the pages reference.
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const { pathToFileURL } = require('node:url');
const { ROOT, readText } = require('../repo-files.js');
const { allRefs } = require('./assets.js');

const gen = () => import(pathToFileURL(path.join(ROOT, 'scripts', 'gen-precache.mjs')).href);
function listed() {
  const box = { self: {} };
  new Function('self', readText('sw-precache.js'))(box.self);
  return box.self.VTOL_PRECACHE;
}

test('R3: sw-precache.js is up to date (list and content hash), so a deployed change always gives a new worker', async () => {
  const g = await gen();
  assert.equal(readText('sw-precache.js'), g.render(), 'run: node scripts/gen-precache.mjs');
  const pc = listed();
  assert.match(pc.hash, /^[0-9a-f]{16}$/);
  assert.deepEqual(pc.assets, g.listAssets());
});

test('R3/R11: every precache entry exists on disk; no duplicates; no development-only files', () => {
  const { assets } = listed();
  assert.equal(new Set(assets).size, assets.length, 'no duplicates');
  assert.equal(assets[0], './');
  for (const a of assets.slice(1)) {
    assert.match(a, /^\.\/[\w./-]+$/, a);
    assert.ok(fs.existsSync(path.join(ROOT, a)) && fs.statSync(path.join(ROOT, a)).isFile(), 'exists: ' + a);
    assert.doesNotMatch(a, /\.(md|txt|py|mjs|ps1|sh)$|LICENSE|^\.\/(?:test|docs|scripts|gcs|protocol|archive|ai)\/|relay\/(?:app\.py|templates|start\.sh)|\/sw(?:-precache)?\.js$/, 'not a runtime asset: ' + a);
  }
});

test('R3: the list covers every category the field needs (pages, js, data, css, fonts, relay map + vendor, img .webp, diagrams, tools, icons, manifest)', () => {
  const set = new Set(listed().assets);
  const want = ['./index.html', './manual.html', './relay/map.html', './tools/latency-clock.html', './manifest.webmanifest', './css/base.css', './css/print.css',
    './data/content.js', './relay/rfmodel.js', './relay/vendor/leaflet/leaflet.js', './relay/vendor/leaflet/leaflet.css', './relay/vendor/leaflet/images/marker-icon.png',
    './fonts/oswald-latin.woff2', './fonts/oswald-latin-ext.woff2', './fonts/share-tech-mono-latin.woff2', './icons/icon-192.png', './icons/icon-512.png',
    './icons/icon-maskable-192.png', './icons/icon-maskable-512.png', './img/client_drone.svg', './js/vendor/qrcode-generator/qrcode.js'];
  for (const w of want) assert.ok(set.has(w), w);
  for (const f of fs.readdirSync(path.join(ROOT, 'js'))) if (f.endsWith('.js')) assert.ok(set.has('./js/' + f), 'js/' + f);
  for (const f of fs.readdirSync(path.join(ROOT, 'img'))) {
    if (f.endsWith('.webp')) assert.ok(set.has('./img/' + f), 'img/' + f);
    if (/\.jpe?g$/.test(f)) assert.ok(!set.has('./img/' + f), 'img/' + f + ': the .webp sibling is precached instead');
  }
});

test('R12(f): js/diagrams.js and every img/diagrams/*.svg are precached', () => {
  const set = new Set(listed().assets);
  assert.ok(set.has('./js/diagrams.js'));
  const svgs = fs.readdirSync(path.join(ROOT, 'img', 'diagrams')).filter(f => f.endsWith('.svg'));
  assert.equal(svgs.length, 16);
  for (const f of svgs) assert.ok(set.has('./img/diagrams/' + f), f);
});

test('R3: every same-origin asset referenced by a precached page, stylesheet, manifest or script is in the list', () => {
  const { assets } = listed();
  const set = new Set(assets.map(a => a.slice(2)));
  const refs = allRefs(assets);
  assert.ok(refs.length > 80, 'found ' + refs.length + ' references');
  const missing = [];
  for (const r of refs) {
    if (/(^|\/)sw\.js$/.test(r.path)) continue;                           // the worker script is never cached
    if (!fs.existsSync(path.join(ROOT, r.path))) { missing.push(r.from + ' → ' + r.ref + ' (no such file)'); continue; }
    if (set.has(r.path)) continue;
    const webp = r.path.replace(/\.(jpe?g|png)$/, '.webp');
    if (r.picture && webp !== r.path && set.has(webp)) continue;          // <picture> fallback: the .webp is what browsers load
    missing.push(r.from + ' → ' + r.ref);
  }
  assert.deepEqual(missing, []);
});

test('R3: node scripts/gen-precache.mjs --check passes (the command for CI / before a commit)', () => {
  const { spawnSync } = require('node:child_process');
  const ok = spawnSync(process.execPath, [path.join(ROOT, 'scripts', 'gen-precache.mjs'), '--check'], { encoding: 'utf8' });
  assert.equal(ok.status, 0, ok.stdout + ok.stderr);
  assert.match(ok.stdout, /up to date \(\d+ assets\)/);
});
